import {ingredients,recipes} from './content.js?v=20260923-15';
import * as C from './core.js?v=20260923-15';
import * as F from './food-store.js?v=20260923-15';
import {parseRecipeText,recognizePhotos} from './recipe-import.js?v=20260923-15';
import {isLocalRecipe} from './regional-food.js?v=20260923-15';
export function createFoodUI(api){const {esc,field,select,check,btn,modal,close,save,money,amount,baseAmount,today}=api,s=()=>api.state(),p=()=>s().profile||C.defaults;
	let filters={type:'all',cost:'',protein:'',time:'',vegetarian:false},ingredientSearch='',recipeDraft=null,entryDraft=null,importedDraft=null,visibleRecipes=12,showAllRegions=false;
const uid=()=> 'custom-'+crypto.randomUUID();
const allowedIngredients=()=>Object.entries(ingredients).filter(([id])=>!s().hiddenIngredients.includes(id));
const macros=n=>`${Math.round(n.kcal)} kcal · ${Math.round(n.protein)} g protein · ${Math.round(n.carbs)} g carbs · ${Math.round(n.fat)} g fat`;
const optionList=()=>allowedIngredients().map(([id,i])=>[id,i.name]);
function importSheet(text=''){modal(`<h2>Add a recipe</h2><form id="recipe-import-form"><label>Paste a recipe<textarea name="recipeText" rows="14" maxlength="50000" required>${esc(text)}</textarea></label><div class="button-row"><label class="button outline">Add photo<input id="recipe-photo" type="file" accept="image/*" capture="environment" multiple hidden></label><button class="primary" type="submit">Import</button></div><p id="ocr-status" class="small muted" aria-live="polite"></p></form>`);}
function importedNutrition(){const servings=Math.max(1,Number(importedDraft.servings)||1),entries=importedDraft.rows.filter(row=>row.match&&Number.isFinite(row.grams)).map(row=>{const factor=row.basis==='cooked'&&/rice|pasta|oat|lentil|noodle/i.test(row.item)?0.4:1;return {nutrition:F.ingredientNutrition(ingredients[row.match],row.grams*factor/servings,p().prices[row.match])};});return F.totals(entries);}
function captureImportForm(form){const values=new FormData(form);importedDraft.name=values.get('name').trim();importedDraft.servings=Number(values.get('servings'));importedDraft.time=Number(values.get('time'));importedDraft.mealType=values.get('mealType');importedDraft.source=values.get('source').trim();importedDraft.steps=values.get('steps').split('\n').map(x=>x.trim()).filter(Boolean);importedDraft.nutritionChoice=values.get('nutritionChoice')||importedDraft.nutritionChoice||'ingredients';for(const [index,row]of importedDraft.rows.entries()){row.match=values.get('match-'+index)||'';row.basis=values.get('basis-'+index)||row.basis||'dry';row.notCounted=!row.match||row.grams===null;}}
function confirmImport(){const draft=importedDraft,n=importedNutrition(),missing=draft.rows.filter(row=>!row.match||row.notCounted).length,creator=draft.creatorNutrition,diff=creator?.kcal?Math.abs(creator.kcal-n.kcal)/creator.kcal:0,groups=[...new Set(draft.rows.map(row=>row.group))],choice=draft.nutritionChoice||'ingredients';modal(`<h2>Check recipe</h2><form id="import-confirm-form">${field('Name','name',draft.name,'text','required maxlength="150"')}<div class="form-grid">${field('Servings','servings',draft.servings,'number','required min="1" max="100"')}${field('Prep and cook time','time',draft.time,'number','required min="1" max="1440"')}${select('Meal type','mealType',draft.mealType,[['breakfast','Breakfast'],['lunch','Lunch'],['dinner','Dinner'],['snack','Snack']])}</div>${field('From','source',draft.source||'Pasted recipe','text','maxlength="300"')}<div class="import-rows">${groups.map(group=>`<section><h3>${esc(group)}</h3>${draft.rows.map((row,index)=>({row,index})).filter(x=>x.row.group===group).map(({row,index})=>`<div class="import-row ${!row.match?'unmatched':''}"><div><strong>${esc(row.read)}</strong>${row.note?`<small>${esc(row.note)}</small>`:''}</div><div>${select('Match','match-'+index,row.match,[['','Skip, not counted'],...optionList()])}${row.match&&row.grams!==null?`<small>${money(F.ingredientNutrition(ingredients[row.match],row.grams/Math.max(1,draft.servings),p().prices[row.match]).cost)} per serving</small>`:btn('Add as new ingredient','food-import-new',`data-index="${index}"`,'text-btn')}${/rice|pasta|oat|lentil|noodle/i.test(row.item)?select('Weight','basis-'+index,row.basis||(/topping/i.test(row.group)?'cooked':'dry'),[['cooked','Cooked'],['dry','Dry']]):''}</div></div>`).join('')}</section>`).join('')}</div><div id="import-total"><strong>${Math.round(n.kcal).toLocaleString()} kcal</strong><span>${missing?`${missing} item${missing===1?'':'s'} not counted yet`:`${Math.round(n.protein)} g protein · ${money(n.cost)} per serving`}</span></div>${creator&&diff>.15?`<fieldset><legend>Nutrition</legend><label><input type="radio" name="nutritionChoice" value="ingredients" ${choice==='ingredients'?'checked':''}> Ingredients add up to ${Math.round(n.kcal)} kcal</label><label><input type="radio" name="nutritionChoice" value="creator" ${choice==='creator'?'checked':''}> Creator says ${Math.round(creator.kcal)} kcal</label></fieldset>`:''}<label>Method<textarea name="steps" rows="8" maxlength="20000">${esc(draft.steps.join('\n'))}</textarea></label><button class="primary full" type="submit">Save recipe</button></form>`);}
async function readPhotos(files){const status=document.querySelector('#ocr-status');if(status)status.textContent='Reading photo';const text=await recognizePhotos(files,progress=>{const target=document.querySelector('#ocr-status');if(target)target.textContent=`Reading photo ${progress}%`;});const box=document.querySelector('#recipe-import-form textarea');if(box)box.value=[box.value.trim(),text].filter(Boolean).join('\n');const target=document.querySelector('#ocr-status');if(target)target.textContent=text.trim()?'Text added':'Couldn’t read that image';}
	function library(own=false){const available=C.allowedRecipes(p()),local=available.filter(r=>isLocalRecipe(r,C.cityInfo(api.region()))),list=(own?available.filter(r=>r.id.startsWith('custom-')):showAllRegions?available:local).filter(r=>(!own||r.id.startsWith('custom-'))&&(filters.type==='all'||r.mealType===filters.type)).filter(r=>{const n=C.nutrition(r,1,p());return (!filters.cost||n.cost<=baseAmount(Number(filters.cost)))&&(!filters.protein||n.protein>=Number(filters.protein))&&(!filters.time||r.time<=Number(filters.time))&&(!filters.vegetarian||Object.keys(r.items).every(id=>ingredients[id].vegetarian));}),shown=list.slice(0,visibleRecipes);return `<div class="section-head"><h2>${own?'My recipes':'Recipe library'}</h2><div class="button-row">${btn('Create recipe','food-new-recipe','','outline')}${btn('Add a recipe','food-import-recipe','','primary')}</div></div><form id="recipe-filter-form" class="catalog-filters">${select('Meal type','type',filters.type,[['all','All meals'],['breakfast','Breakfast'],['lunch','Lunch'],['dinner','Dinner'],['snack','Snacks']])}${field(`Max cost (${api.region().currency})`,'cost',filters.cost,'number','min="0" step=".1"')}${field('Min protein (g)','protein',filters.protein,'number','min="0"')}${field('Max prep (min)','time',filters.time,'number','min="1"')}${check('Vegetarian','vegetarian',filters.vegetarian)}<button class="small-button" type="submit">Apply filters</button></form><p class="small muted">${list.length} recipes</p><div class="recipe-grid">${shown.map(r=>{const n=C.nutrition(r,1,p());return `<article class="card"><span class="tag">${esc(r.mealType)}</span><h3>${esc(r.name)}</h3><p>${macros(n)}</p><p class="small">${r.time} min · ${money(n.cost)} per serving</p><div class="button-row">${btn('View recipe','recipe',`data-id="${r.id}"`,'small-button')}${btn('Log meal','food-log-recipe',`data-id="${r.id}"`,'small-button')}${r.id.startsWith('custom-')?btn('Edit','food-edit-recipe',`data-id="${r.id}"`,'small-button'):''}</div></article>`;}).join('')||'<p>No matching recipes</p>'}</div>${shown.length<list.length?`<div class="show-more-row">${btn(`Show ${Math.min(12,list.length-shown.length)} more`,'food-show-more','','outline')}</div>`:''}${!own&&!showAllRegions&&available.length>local.length?`<div class="show-more-row">${btn('Show all recipes','food-show-all-regions','','outline')}</div>`:''}`;}
function ingredientPage(){return `<div class="section-head"><h2>My ingredients</h2>${btn('Add ingredient','food-new-ingredient','','primary')}</div><p class="small muted">Pack prices in ${api.region().currency}</p><form id="ingredient-search-form" class="button-row">${field('Search ingredients','search',ingredientSearch,'search')}<button class="small-button">Search</button></form><div class="ingredient-list">${allowedIngredients().filter(([id,i])=>i.name.toLowerCase().includes(ingredientSearch.toLowerCase())).map(([id,i])=>{const pr=p().prices[id],pack=pr?.pack||i.pack,price=pr?.price??i.price;return `<article class="ingredient-item"><div><h3>${esc(i.name)}</h3><p class="small">${price?money(price):'Add price'} / ${esc(i.packageLabel||pack+' '+(pr?'g':i.unit))}</p><p class="small muted">${macros(i)} per 100 g</p>${i.store?`<p class="small">${esc(i.store)}</p>`:''}</div><div class="button-row">${btn('Edit','food-edit-ingredient',`data-id="${id}"`,'small-button')}${btn('Delete','food-delete-ingredient',`data-id="${id}"`,'small-button')}</div></article>`;}).join('')}</div>`;}
function editIngredient(id='',seed=null,importRow=''){const i=ingredients[id]||seed||{name:'',pack:1000,price:0,unit:'g',gramsPerUnit:1,kcal:0,protein:0,carbs:0,fat:0,allergens:[],vegetarian:true,store:''},price=p().prices[id];modal(`<h2>${id?'Edit':'Add'} ingredient</h2><form id="ingredient-form" data-id="${esc(id)}" data-import-row="${esc(importRow)}">${!id?`<details><summary>Use built-in ingredient</summary>${select('Find ingredient','copyIngredient','',[['','Choose ingredient'],...optionList()])}${btn('Use selected','food-copy-ingredient','','small-button')}</details>`:''}${field('Name','name',i.name,'text','required maxlength="150"')}<div class="form-grid">${field('Pack size','pack',price?.pack||i.pack,'number','required min=".01" max="100000" step="any"')}${select('Pack unit','unit',price?'g':i.unit,[['g','g'],['ml','ml'],['each','Each']])}${field('Grams per unit','gramsPerUnit',price?1:i.gramsPerUnit,'number','required min=".001" max="10000" step="any"')}${field(`Pack price (${api.region().currency})`,'price',amount(price?.price??i.price),'number','required min="0" max="100000" step=".01"')}</div><details><summary>Unit conversion</summary><p>Use 1 for grams. For ml or each, enter the weight of one unit in grams.</p></details>${field('Store','store',i.store||'','text','maxlength="150"')}<h3>Per 100 g</h3><div class="form-grid">${['kcal','protein','carbs','fat'].map(k=>field(k==='kcal'?'Energy (kcal)':k[0].toUpperCase()+k.slice(1)+' (g)',k,i[k],'number',`required min="0" max="${k==='kcal'?1000:100}" step="any"`)).join('')}</div>${check('Vegetarian','vegetarian',i.vegetarian)}<label>Allergens</label><div class="check-grid">${['egg','soy','fish','gluten','legume','milk','peanut','tree nut','shellfish','sesame'].map(a=>check(a==='tree nut'?'Tree nuts':a[0].toUpperCase()+a.slice(1),'allergens',i.allergens.includes(a),a)).join('')}</div><button class="primary" type="submit">Save ingredient</button></form>`);}
function captureRecipe(){const f=document.querySelector('#custom-recipe-form');if(!f)return;const d=new FormData(f);Object.assign(recipeDraft,{name:d.get('name'),servings:Number(d.get('servings')),time:Number(d.get('time')),mealType:d.get('mealType'),steps:d.get('steps'),gear:d.getAll('gear')});recipeDraft.rows=[...f.querySelectorAll('.recipe-ingredient-row')].map(row=>({id:row.querySelector('select').value,grams:Number(row.querySelector('input').value)}));}
function recipeEditor(id,keep=false){if(!keep){const r=recipes.find(r=>r.id===id);recipeDraft=r?{id:r.id,name:r.name,servings:r.servings,time:r.time,mealType:r.mealType,steps:r.steps.join('\n'),gear:r.gear,rows:Object.entries(r.items).map(([id,g])=>({id,grams:g*r.servings}))}:{id:'',name:'',servings:1,time:15,mealType:'lunch',steps:'',gear:[],rows:[{id:allowedIngredients()[0]?.[0],grams:100}]};}const r=recipeDraft;modal(`<h2>${r.id?'Edit':'Create'} recipe</h2><form id="custom-recipe-form">${field('Name','name',r.name,'text','required maxlength="150"')}<div class="form-grid">${field('Makes servings','servings',r.servings,'number','required min=".25" max="100" step=".25"')}${field('Prep time (min)','time',r.time,'number','required min="1" max="1440"')}${select('Meal type','mealType',r.mealType,['breakfast','lunch','dinner','snack'].map(x=>[x,x[0].toUpperCase()+x.slice(1)]))}</div><h3>Ingredients</h3>${r.rows.map((row,i)=>`<div class="recipe-ingredient-row">${select('Ingredient','ingredient-'+i,row.id,optionList())}${field('Grams','grams-'+i,row.grams,'number','required min=".1" max="100000" step="any"')}${btn('×','food-remove-row',`data-index="${i}" aria-label="Remove ingredient"`,'icon-button')}</div>`).join('')}${btn('Add row','food-add-row','','small-button')}<div id="recipe-live-total" aria-live="polite"></div><label>Kitchen</label><div class="check-grid">${['stove','rice cooker','microwave','fridge','blender'].map(g=>check(g[0].toUpperCase()+g.slice(1),'gear',r.gear.includes(g),g)).join('')}</div><label>Method<textarea name="steps" rows="4" maxlength="10000">${esc(r.steps)}</textarea></label><div class="button-row"><button class="primary" type="submit">Save recipe</button>${r.id?btn('Delete recipe','food-delete-recipe',`data-id="${r.id}"`,'small-button'):''}</div></form>`);recipePreview();}
function recipePreview(){captureRecipe();if(!recipeDraft.servings)return;const n=F.totals(recipeDraft.rows.filter(x=>ingredients[x.id]).map(x=>({nutrition:F.ingredientNutrition(ingredients[x.id],x.grams/recipeDraft.servings,p().prices[x.id])})));document.querySelector('#recipe-live-total').innerHTML=`<p>${macros(n)}<br>${money(n.cost)} per serving</p>`;}
function logPage(){const day=api.selectedDay()||today(),entries=s().foodEntries.filter(e=>e.day===day).sort((a,b)=>((C.mins(a.time)-C.mins(C.settingsFor(p(),day).wake)+1440)%1440)-((C.mins(b.time)-C.mins(C.settingsFor(p(),day).wake)+1440)%1440)),n=F.totals(entries),recent=[...s().foodEntries].reverse().filter((e,i,arr)=>arr.findIndex(x=>x.kind===e.kind&&x.ref===e.ref&&x.name===e.name)===i).sort((a,b)=>Number(s().foodFavorites.includes(b.kind+':'+(b.ref||b.name)))-Number(s().foodFavorites.includes(a.kind+':'+(a.ref||a.name)))).slice(0,6);return `<div class="section-head"><h2>What I ate</h2>${btn('Log food','food-add-entry','','primary')}</div><p>${macros(n)} · ${money(n.cost)}</p>${recent.length?`<h3>Recent & favourites</h3><div class="recent-foods">${recent.map(e=>btn(esc(e.name),'food-repeat',`data-id="${e.id}"`,'small-button')).join('')}</div>`:''}<div class="food-log-list">${entries.map(e=>`<article class="ingredient-item"><div><h3>${esc(e.name)}</h3><p class="small">${e.time} · ${e.kind==='recipe'?e.amount+' serving(s)':e.kind==='ingredient'?e.amount+' g':'Quick entry'}</p><p class="small">${macros(e.nutrition)} · ${money(e.nutrition.cost)}</p></div><div class="button-row">${btn('Edit','food-edit-entry',`data-id="${e.id}"`,'small-button')}${btn('Delete','food-delete-entry',`data-id="${e.id}"`,'small-button')}${btn(s().foodFavorites.includes(e.kind+':'+(e.ref||e.name))?'Saved':'Save','food-favourite',`data-id="${e.id}" aria-label="Save favourite food"`,'small-button')}</div></article>`).join('')||'<p>No food logged</p>'}</div>${check('Day complete','food-day-complete',s().foodLogs.find(f=>f.day===day)?.complete)}${btn('Daily total','food-total','','small-button')}`;}
function entryEditor(id='',preset=null){entryDraft=id?structuredClone(s().foodEntries.find(e=>e.id===id)):{id:'',day:api.selectedDay()||today(),time:new Intl.DateTimeFormat('en-GB',{timeZone:C.cityInfo(api.region()).zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date()),kind:preset?.kind||'recipe',ref:preset?.ref||C.allowedRecipes(p())[0]?.id,amount:1,name:'',nutrition:F.zero()};drawEntry();}
function drawEntry(){const e=entryDraft;modal(`<h2>${e.id?'Edit food':'Log food'}</h2><form id="food-entry-form">${select('Entry type','kind',e.kind,[['recipe','Recipe'],['ingredient','Ingredient'],['quick','Quick entry']])}<div class="form-grid">${field('Day','day',e.day,'date','required')}${field('Time','time',e.time,'time','required')}</div>${e.kind==='quick'?`${field('Name','name',e.name,'text','required maxlength="150"')}<div class="form-grid">${F.nutrientKeys.map(k=>field(k==='cost'?`Cost (${api.region().currency})`:k==='kcal'?'Energy (kcal)':k[0].toUpperCase()+k.slice(1)+' (g)',k,k==='cost'?amount(e.nutrition[k]):e.nutrition[k],'number','required min="0" max="100000" step="any"')).join('')}</div>`:`${select(e.kind==='recipe'?'Recipe':'Ingredient','ref',e.ref,e.kind==='recipe'?recipes.filter(r=>!s().hiddenIngredients.some(id=>r.items[id])).map(r=>[r.id,r.name]):optionList())}${field(e.kind==='recipe'?'Servings':'Amount (g)','amount',e.amount,'number','required min=".1" max="10000" step="any"')}<div id="entry-preview" aria-live="polite"></div>`}<button class="primary" type="submit">Save food</button></form>`);entryPreview();}
function entryValues(){const f=document.querySelector('#food-entry-form'),d=new FormData(f),kind=d.get('kind'),ref=d.get('ref'),amount=Number(d.get('amount'))||1;let name,n;if(kind==='quick'){name=d.get('name').trim();n=Object.fromEntries(F.nutrientKeys.map(k=>[k,k==='cost'?baseAmount(Number(d.get(k))):Number(d.get(k))]));}else if(kind==='recipe'){const r=C.recipe(ref);name=r.name;n=C.nutrition(r,amount,p());}else{name=ingredients[ref].name;n=F.ingredientNutrition(ingredients[ref],amount,p().prices[ref]);}return {id:entryDraft.id||uid(),kind,ref:ref||undefined,amount,day:d.get('day'),time:d.get('time'),name,nutrition:n};}
function entryPreview(){const box=document.querySelector('#entry-preview');if(box){const e=entryValues();box.innerHTML=`<p>${macros(e.nutrition)} · ${money(e.nutrition.cost)}</p>`;}}
function record(e){const old=s().foodEntries.find(x=>x.id===e.id);F.validateFoodExtension({foodEntries:[e]});save('Saved',()=>{s().foodEntries=s().foodEntries.filter(x=>x.id!==e.id);s().foodEntries.push(e);if(old)F.syncDay(s(),old.day);F.syncDay(s(),e.day);const m=s().mealLogs.find(m=>m.id===e.id);if(m&&e.kind==='recipe'){m.recipe=e.ref;m.servings=e.amount;m.time=e.time;m.day=e.day;m.nutrition=e.nutrition;}});}
function action(a,el){const id=el.dataset.id;if(!a.startsWith('food-')||['food-total'].includes(a))return false;
	 if(a==='food-new-ingredient')editIngredient();if(a==='food-edit-ingredient')editIngredient(id);if(a==='food-import-recipe')importSheet();if(a==='food-import-new'){const index=Number(el.dataset.index),row=importedDraft.rows[index];editIngredient('',{name:row.item,pack:Math.max(1,row.grams||100),price:0,unit:'g',gramsPerUnit:1,kcal:0,protein:0,carbs:0,fat:0,allergens:[],vegetarian:true,store:''},String(index));}
	 if(a==='food-show-more'){visibleRecipes+=12;api.render();}if(a==='food-show-all-regions'){showAllRegions=true;visibleRecipes=12;api.render();}
 if(a==='food-copy-ingredient'){const id=document.querySelector('[name=copyIngredient]').value;if(id)editIngredient(id);}
 if(a==='food-delete-ingredient'){if(recipes.some(r=>r.items[id])||s().foodEntries.some(e=>e.ref===id))throw Error('Remove this ingredient from recipes and logs first');save('Saved',()=>{s().hiddenIngredients.push(id);});}
 if(a==='food-new-recipe')recipeEditor();if(a==='food-edit-recipe')recipeEditor(id);
 if(a==='food-add-row'){captureRecipe();recipeDraft.rows.push({id:allowedIngredients()[0][0],grams:100});recipeEditor('',true);}
 if(a==='food-remove-row'){captureRecipe();recipeDraft.rows.splice(Number(el.dataset.index),1);recipeEditor('',true);}
 if(a==='food-delete-recipe'){if(s().plan?.days.some(d=>d.meals.some(m=>m.recipe===id))||s().mealLogs.some(m=>m.recipe===id)||s().foodEntries.some(e=>e.ref===id)||s().extraGroceries.some(m=>m.recipe===id))throw Error('Remove this recipe from your plan and logs first');save('Saved',()=>{s().customRecipes=s().customRecipes.filter(r=>r.id!==id);s().favorites=s().favorites.filter(x=>x!==id);});close();}
 if(a==='food-add-entry')entryEditor();if(a==='food-edit-entry')entryEditor(id);if(a==='food-log-recipe')entryEditor('',{kind:'recipe',ref:id});
 if(a==='food-delete-entry'){const e=s().foodEntries.find(e=>e.id===id);save('Saved',()=>{s().foodEntries=s().foodEntries.filter(e=>e.id!==id);s().mealLogs=s().mealLogs.filter(e=>e.id!==id);F.syncDay(s(),e.day);});}
 if(a==='food-repeat'){const e=structuredClone(s().foodEntries.find(e=>e.id===id));e.id=uid();e.day=api.selectedDay()||today();e.time=new Intl.DateTimeFormat('en-GB',{timeZone:C.cityInfo(api.region()).zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());if(e.kind==='recipe'&&C.recipe(e.ref))e.nutrition=C.nutrition(C.recipe(e.ref),e.amount,p());if(e.kind==='ingredient'&&ingredients[e.ref])e.nutrition=F.ingredientNutrition(ingredients[e.ref],e.amount,p().prices[e.ref]);record(e);}
 if(a==='food-favourite'){const e=s().foodEntries.find(e=>e.id===id),key=e.kind+':'+(e.ref||e.name);save('Saved',()=>{s().foodFavorites=s().foodFavorites.includes(key)?s().foodFavorites.filter(x=>x!==key):[...s().foodFavorites,key];});}
 return true;
}
function submit(f){const d=new FormData(f),get=k=>d.get(k);
	 if(f.id==='recipe-import-form'){importedDraft=parseRecipeText(get('recipeText'),ingredients);if(!importedDraft.rows.length){const status=document.querySelector('#ocr-status');if(status)status.textContent='No ingredients found';return true;}confirmImport();return true;}
	 if(f.id==='import-confirm-form'){captureImportForm(f);const items={};for(const row of importedDraft.rows){if(!row.match||!Number.isFinite(row.grams))continue;const factor=row.basis==='cooked'&&/rice|pasta|oat|lentil|noodle/i.test(row.item)?0.4:1;items[row.match]=(items[row.match]||0)+row.grams*factor/importedDraft.servings;}if(!Object.keys(items).length)throw Error('Match one ingredient');const record={id:uid(),name:importedDraft.name,items,servings:importedDraft.servings,time:importedDraft.time,prep:importedDraft.time,cook:0,mealType:importedDraft.mealType,tag:'My recipe',gear:[],steps:importedDraft.steps,subs:'',storage:'',source:importedDraft.source,importedRows:importedDraft.rows,creatorNutrition:importedDraft.creatorNutrition,nutritionChoice:importedDraft.nutritionChoice||'ingredients'};F.validateFoodExtension({customRecipes:[record]});if(save('Recipe saved',()=>s().customRecipes.push(record))){importedDraft=null;close();}return true;}
	 if(f.id==='recipe-filter-form'){filters={type:get('type'),cost:get('cost'),protein:get('protein'),time:get('time'),vegetarian:d.has('vegetarian')};visibleRecipes=12;api.render();return true;}
 if(f.id==='ingredient-search-form'){ingredientSearch=get('search');api.render();return true;}
 if(f.id==='ingredient-form'){const id=f.dataset.id||uid(),i={name:get('name').trim(),pack:Number(get('pack')),unit:get('unit'),gramsPerUnit:get('unit')==='g'?1:Number(get('gramsPerUnit')),price:baseAmount(Number(get('price'))),store:get('store').trim(),allergens:d.getAll('allergens'),vegetarian:d.has('vegetarian'),estimated:false,measure:'Edible grams',...Object.fromEntries(['kcal','protein','carbs','fat'].map(k=>[k,Number(get(k))]))};const original=ingredients[id];if(original&&['kcal','protein','carbs','fat'].every(k=>original[k]===i[k]))i.nutritionSource=original.nutritionSource;F.validateFoodExtension({customIngredients:{[id]:i}});if(save('Saved',()=>{s().customIngredients[id]=i;delete p().prices[id];})){if(f.dataset.importRow!==''){const row=importedDraft.rows[Number(f.dataset.importRow)];row.match=id;row.notCounted=false;confirmImport();}else close();}return true;}
 if(f.id==='custom-recipe-form'){captureRecipe();const r=recipeDraft;if(!r.name.trim()||!r.rows.length)throw Error('Add a name and at least one ingredient');const items={};for(const row of r.rows){if(!ingredients[row.id]||row.grams<=0)throw Error('Choose ingredients and positive amounts');items[row.id]=(items[row.id]||0)+row.grams/r.servings;}const record={id:r.id||uid(),name:r.name.trim(),items,servings:r.servings,time:r.time,prep:r.time,cook:0,mealType:r.mealType,tag:'My recipe',gear:r.gear,steps:r.steps.trim()?r.steps.trim().split('\n'):['Prepare and combine the ingredients'],subs:'',storage:''};F.validateFoodExtension({customRecipes:[record]});if(save('Saved',()=>{s().customRecipes=s().customRecipes.filter(x=>x.id!==record.id);s().customRecipes.push(record);}))close();return true;}
 if(f.id==='food-entry-form'){record(entryValues());close();return true;}return false;
}
function change(e){if(e.target.closest?.('#import-confirm-form')&&(e.target.name.startsWith('match-')||e.target.name.startsWith('basis-'))){captureImportForm(e.target.form);confirmImport();return;}if(e.target.id==='recipe-photo'&&e.target.files.length)readPhotos([...e.target.files]).catch(()=>{const status=document.querySelector('#ocr-status');if(status)status.textContent='Couldn’t read that image';});if(e.target.name==='food-day-complete'){save('Saved',()=>{const day=api.selectedDay()||today();F.syncDay(s(),day);s().foodLogs.find(f=>f.day===day).complete=e.target.checked;});}if(e.target.closest('#food-entry-form')&&e.target.name==='kind'){const d=new FormData(e.target.form);entryDraft.day=d.get('day');entryDraft.time=d.get('time');entryDraft.kind=e.target.value;entryDraft.amount=1;entryDraft.ref=entryDraft.kind==='ingredient'?allowedIngredients()[0][0]:recipes[0].id;drawEntry();}}
function input(e){if(e.target.closest('#custom-recipe-form'))recipePreview();if(e.target.closest('#food-entry-form')&&e.target.name!=='kind')entryPreview();}
function paste(e){if(!e.target.closest?.('#recipe-import-form'))return;const files=[...e.clipboardData.items].filter(item=>item.type.startsWith('image/')).map(item=>item.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();readPhotos(files).catch(()=>{const status=document.querySelector('#ocr-status');if(status)status.textContent='Couldn’t read that image';});}}
return {library,ingredientPage,logPage,entryEditor,action,submit,change,input,paste,macros};}
